import type { Types } from '@cornerstonejs/core';
export type AnnotationMetadata = Types.ViewReference & {
    toolName: string;
    cameraPosition?: Types.Point3;
    viewUp?: Types.Point3;
    segmentColor?: any;
    enabledElement?: Types.IEnabledElement;
};
export type StatItem = {
    name: string;
    label: string;
    value: number | number[];
    unit?: string;
    pointIJK?: Types.Point3;
    pointLPS?: Types.Point3;
};
export interface CachedStats {
    Modality?: string;
    area?: number | number[];
    length?: number | number[];
    width?: number | number[];
    unit?: string;
    areaUnit?: string;
    max?: number | number[];
    mean?: number | number[];
    min?: number | number[];
    radius?: number;
    radiusUnit?: string;
    perimeter?: number;
    statsArray?: StatItem[];
    [key: string]: unknown;
}
export interface VolumeStats {
    pointsInVolume: Types.Point3[];
    projectionPoints: Types.Point3[] | Types.Point3[][];
    projectionPointsImageIds?: string[];
    statistics?: unknown;
}
export type AnnotationData = {
    handles?: Handles;
    cachedStats?: Record<string, CachedStats> | VolumeStats;
    label?: string;
    contour?: Contour;
    isOpenUShapeContour?: boolean | 'farthestT' | 'lineSegment' | 'orthogonalT';
    [key: string]: unknown;
};
export type AnnotationDataStatsByTargetId = Omit<AnnotationData, 'cachedStats'> & {
    cachedStats: Record<string, CachedStats>;
};
export type Annotation = {
    annotationUID?: string;
    parentAnnotationUID?: string;
    interpolationUID?: string;
    childAnnotationUIDs?: string[];
    highlighted?: boolean;
    isLocked?: boolean;
    isVisible?: boolean;
    invalidated?: boolean;
    isSelected?: boolean;
    autoGenerated?: boolean;
    metadata?: AnnotationMetadata;
    data: AnnotationData;
    predecessorImageId?: string;
};
export type Contour = {
    polyline?: Types.Point3[];
    pointsManager?: Types.IPointsManager<Types.Point3>;
    closed?: boolean;
};
export type Annotations = Array<Annotation>;
export type GroupSpecificAnnotations = {
    [toolName: string]: Annotations;
};
export type AnnotationState = {
    [key: string]: GroupSpecificAnnotations;
};
export type Handles = {
    points?: Types.Point3[];
    activeHandleIndex?: number | null;
    textBox?: {
        hasMoved?: boolean;
        worldPosition?: Types.Point3;
        worldBoundingBox?: {
            topLeft: Types.Point3;
            topRight: Types.Point3;
            bottomLeft: Types.Point3;
            bottomRight: Types.Point3;
        };
    };
    [key: string]: unknown;
};
